// Global error handler - add at the END of middleware chain
app.use((err, req, res, next) => {
  // Log error internally (never expose to client)
  console.error(`[${new Date().toISOString()}] Error:`, {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
  });

