const morgan = require('morgan');

// Use 'combined' format in production for more details
app.use(morgan('combined', {
  skip: (req, res) => req.url === '/health', // Skip health checks
}));

// Custom security logging
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    if (res.statusCode >= 400) {
      console.warn(`[SECURITY] ${req.method} ${req.url} - ${res.statusCode} - ${Date.now() - start}ms - IP: ${req.ip}`);
