app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

---

### 🟠 MEDIUM: No CORS Configuration (OWASP A05:2021 - Security Misconfiguration)

**Issue:** No CORS policy is defined. Depending on deployment, this could either be too permissive (allowing any origin) or cause issues.

**Recommendation:** Configure CORS explicitly:

```javascript
const cors = require('cors');

const corsOptions = {
  origin: ['https://yourdomain.com'], // Whitelist allowed origins
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
};

app.use(cors(corsOptions));
