## 📝 Recommended Secrets Architecture

```javascript
// secrets.js - Centralized secrets management
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
    this.cache = new Map();
    this.cacheTTL = 5 * 60 * 1000; // 5 minutes
  }

  async getSecret(secretId) {
    // Check cache
    const cached = this.cache.get(secretId);
    if (cached && Date.now() < cached.expiry) {
      return cached.value;
    }

    // Fetch from secrets manager
    const command = new GetSecretValueCommand({ SecretId: secretId });
    const response = await this.client.send(command);

    const value = response.SecretString 
      ? JSON.parse(response.SecretString)
      : response.SecretBinary;

    // Cache it
    this.cache.set(secretId, {
      value,
      expiry: Date.now() + this.cacheTTL,
    });

    return value;
  }

  // For local development only
  static loadDevelopmentSecrets() {
    if (process.env.NODE_ENV === 'production') {
      throw new Error('Cannot use .env files in production!');
    }
    require('dotenv').config();
  }
}

module.exports = new SecretsManager();
```

