        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw new Error('Failed to retrieve secret');
    }
  }

  // Clear cache (useful for rotation)
  clearCache() {
    this.cache.clear();
  }
}

