const Joi = require('joi');

const envSchema = Joi.object({
  NODE_ENV: Joi.string().valid('development', 'staging', 'production').required(),
  PORT: Joi.number().default(3000),
  DATABASE_URL: Joi.string().uri().required(),
  AWS_ACCESS_KEY_ID: Joi.string().pattern(/^AKIA[0-9A-Z]{16}$/).required(),
  AWS_SECRET_ACCESS_KEY: Joi.string().min(40).required(),
  STRIPE_SECRET_KEY: Joi.string().pattern(/^sk_(live|test)_[a-zA-Z0-9]+$/).required(),
  API_KEY: Joi.string().min(32).required(),
}).unknown(); // Allow other env vars

function validateEnv() {
  const { error, value } = envSchema.validate(process.env);

  if (error) {
