Here's a complete secure configuration approach:

```javascript
// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecureConfig {
  #secrets = {};
  #initialized = false;

  async initialize() {
    if (this.#initialized) return;

    if (process.env.NODE_ENV === 'production') {
      await this.#loadFromSecretsManager();
    } else {
      this.#loadFromEnv();
    }

    this.#validateSecrets();
    this.#initialized = true;
  }

  async #loadFromSecretsManager() {
    const client = new SecretsManagerClient({ region: 'us-east-1' });
    const command = new GetSecretValueCommand({ SecretId: 'app/production' });
    const response = await client.send(command);
    this.#secrets = JSON.parse(response.SecretString);
  }

  #loadFromEnv() {
    // Only for development - never in production
    require('dotenv').config();
    this.#secrets = {
      databaseUrl: process.env.DATABASE_URL,
      stripeKey: process.env.STRIPE_SECRET_KEY,
      apiKey: process.env.API_KEY,
    };
  }

  #validateSecrets() {
    const required = ['databaseUrl', 'stripeKey', 'apiKey'];
    const missing = required.filter(key => !this.#secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }

  get(key) {
    if (!this.#initialized) {
      throw new Error('Config not initialized. Call initialize() first.');
    }
    return this.#secrets[key];
  }
}

module.exports = new SecureConfig();
```

