app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

---

### 2. No Security Headers (Helmet)
**Severity: High**  
**OWASP Category: A05:2021 - Security Misconfiguration**

The application lacks security headers that protect against XSS, clickjacking, MIME-type sniffing, and other attacks.

**Recommendation:**
```javascript
const helmet = require('helmet');
app.use(helmet());

// Or configure specific headers:
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  xssFilter: true,
