### 4. No Authentication/Authorization
**Severity: High**  
**OWASP Category: A01:2021 - Broken Access Control, A07:2021 - Identification and Authentication Failures**

The `/users` endpoint exposes user data (including emails) without any authentication.

**Recommendation:**
```javascript
const jwt = require('jsonwebtoken');

// Authentication middleware
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token provided' });
  }

  const token = authHeader.substring(7);

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
};

// Protect sensitive endpoints
app.get('/users', authenticate, (req, res) => {
  // Check authorization (role-based)
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }
  // ... return users
});
```

