Here's how `app.js` should load secrets securely:

```javascript
// app.js - Secure secrets loading
const express = require('express');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function loadSecrets() {
  // In production, use secrets manager
  if (process.env.NODE_ENV === 'production') {
    const client = new SecretsManagerClient({ 
      region: process.env.AWS_REGION || 'us-east-1' 
    });

    const response = await client.send(
      new GetSecretValueCommand({ SecretId: process.env.SECRET_NAME })
    );

    const secrets = JSON.parse(response.SecretString);

    // Set in memory only, never write to disk
    return {
      databaseUrl: secrets.DATABASE_URL,
      stripeKey: secrets.STRIPE_SECRET_KEY,
      anthropicKey: secrets.ANTHROPIC_API_KEY,
    };
  }

  // In development, require explicit env vars (no .env files)
  return {
    databaseUrl: process.env.DATABASE_URL,
    stripeKey: process.env.STRIPE_SECRET_KEY,
    anthropicKey: process.env.ANTHROPIC_API_KEY,
  };
}

async function startServer() {
  const secrets = await loadSecrets();

  // Validate secrets loaded
  if (!secrets.databaseUrl) {
    console.error('Missing DATABASE_URL');
    process.exit(1);
  }

  const app = express();

  // ... rest of app setup

  app.listen(process.env.PORT || 3000);
}

startServer().catch(err => {
  console.error('Failed to start server:', err.message);
  process.exit(1);
});
```

